kGift_Pack[3200755][90]["Option"][2]={}tFeedBackGift_Pack[3200755][90]["Option"][2]["Item_ID"]=680029tFeedBackGift_Pack[3200755][90]["Option"][2]["ItemAttr"]="0 1 3 0 0 0 0 0 0 0 0 255 255"function FeedBackGift(nItemId)	if not User_CheckLeftSpace(tFeedBackGift_Space[nItemId]) then		Sys_MsgBox(string.format(tFeedBackGift_Text["Space"],tFeedBackGift_Space[nItemId]))			return	end	    if not Item_ChkAccItem(nItemId,1) then       return    end    if not Item_DelItem(nItemId) then       return    end 	if nItemId == 3200753 then		tFeedBackGift_GiftData[3200753]["RewardItem"][2]["Id"] = FeedBackGiftFlower()			end	if Get_UserLevel() >= G_User_MaxLev then		tFeedBackGift_GiftData[nItemId]["Talk"] = tFeedBackGift_Text["Talk2"][nItemId]	elseif nItemId == 3200753 then		tFeedBackGift_GiftData[3200753]["Talk"] = tFeedBackGift_Text["Talk"][3200753][Get_UserSex()]	else		tFeedBackGift_GiftData[nItemId]["Talk"] = tFeedBackGift_Text["Talk"][nItemId]	end 	RewardTemplate_Reward(tFeedBackGift_GiftData[nItemId])end		function FeedBackGiftFlower()	if Get_UserSex() == 1 then		return 751099	else		return 756099	endend	--打开礼包function FeedBackGift_UsePack(nItemId)    local tPack=tFeedBackGift_Pack[nItemId]    --判断职业，获得对应的物品ID      local nPro=Get_UserProfession()    if nPro>=100 and nPro <= 145 then        nPro=100    elseif nPro >= 160 and nPro <= 165 then		nPro=160	else        nPro=nPro-nPro%10    end         --0表示不再配置表的共用职业    if tPack[nPro]==nil then        nPro=0    end    if tPack[nPro]["DialogIndex"] ~= nil then              LinkItemGossipFunc_New(nItemId,tPack[nPro]["DialogIndex"])       return     end    FeedBackGift_Reward(nItemId,tPack[nPro]["Item"]["Item_ID"],tPack[nPro]["Item"]["ItemAttr"])end --选项function FeedBackGift_SelectOption(nPackId,nPro,nOption)   local tItem=tFeedBackGift_Pack[nPackId][nPro]["Option"][nOption]   FeedBackGift_Reward(nPackId,tItem["Item_ID"],tItem["ItemAttr"]) end--获得物品function FeedBackGift_Reward(nPackId,nItemId,sItemAttr)    if not Item_ChkAccItem(nPackId,1) then       return    end    if not Item_DelItem(nPackId) then       return    end 	local tReward = {}	tReward["RewardItem"] = {}					tReward["RewardItem"][1] = {}					tReward["RewardItem"][1]["Id"] = nItemId		tReward["RewardItem"][1]["Attr"] = sItemAttr		tReward["Log"] = string.format(sFeedBackGift_Log,nPackId,nItemId)	tReward["RewardEffect"] = {}	tReward["RewardEffect"]["Effect"] = sFeedBackGift_Effect		if nItemId == 619029 then		tReward["Talk"] =string.format(tFeedBackGift_Text["619029"],tFeedBackGift_Text["ItemName"][nItemId])	else		tReward["Talk"] =string.format(tFeedBackGift_Text["AwardItem"],tFeedBackGift_Text["ItemName"][nItemId])	end	RewardTemplate_Reward(tReward)end ------------------------------------------------------------------------------tItem[3200750] = tItem[3200750] or {}tItem[3200750]["Function"] = function(nItemId,sItemName)	FeedBackGift(nItemId)endtItem[3200751] = tItem[3200751] or {}tItem[3200751]["Function"] = function(nItemId,sItemName)	FeedBackGift(nItemId)endtItem[3200752] = tItem[3200752] or {}tItem[3200752]["Function"] = function(nItemId,sItemName)	FeedBackGift(nItemId)endtItem[3200753] = tItem[3200753] or {}tItem[3200753]["Function"] = function(nItemId,sItemName)	FeedBackGift(nItemId)endtItem[3200754] = tItem[3200754] or {}tItem[3200754]["Function"] = function(nItemId,sItemName)	FeedBackGift(nItemId)end--武器礼包tItem[3200755]=tItem[3200755] or {}tItem[3200755]["Function"]=function(nItemId,sItemName)    FeedBackGift_UsePack(nItemId)end--武器勇士对话tItem[3200755]["Text6-1"]={111}tItem[3200755]["Text111"]=tFeedBackGift_Text["Weapon"]tItem[3200755]["tOption6-1"]={61,62,63,64}tItem[3200755]["Option61"]=tFeedBackGift_Text["ItemName"][410029]tItem[3200755]["Option62"]=tFeedBackGift_Text["ItemName"][420029]tItem[3200755]["Option63"]=tFeedBackGift_Text["ItemName"][480029]tItem[3200755]["Option64"]=tFeedBackGift_Text["ReGive"]